export const REVIEW_SPIN_THRESHOLD=10;
export const REVIEW_SLOT_EXIT_THRESHOLD=5;
export const REVIEW_REQUEST_LIMIT=2;
export const REVIEW_RETRY_MS=7*24*60*60*1000;
export const REVIEW_COOLDOWN_MS=120*24*60*60*1000;

export interface ReviewPromptState{
 version:1;
 completedSpins:number;
 slotExits:number;
 requestCount:number;
 lastAttemptAt:number;
 lastRequestAt:number;
}

export function emptyReviewPromptState():ReviewPromptState{return {version:1,completedSpins:0,slotExits:0,requestCount:0,lastAttemptAt:0,lastRequestAt:0};}

function count(value:unknown){return Number.isFinite(value)&&Number(value)>=0?Math.floor(Number(value)):0;}

export function parseReviewPromptState(raw:string|null):ReviewPromptState{
 try{
  const value=JSON.parse(raw||'null') as Partial<ReviewPromptState>|null;
  if(!value||value.version!==1)return emptyReviewPromptState();
  return {version:1,completedSpins:count(value.completedSpins),slotExits:count(value.slotExits),requestCount:count(value.requestCount),lastAttemptAt:count(value.lastAttemptAt),lastRequestAt:count(value.lastRequestAt)};
 }catch{return emptyReviewPromptState();}
}

export function completedReviewSpin(state:ReviewPromptState):ReviewPromptState{return {...state,completedSpins:state.completedSpins+1};}
export function completedSlotVisit(state:ReviewPromptState):ReviewPromptState{return {...state,slotExits:state.slotExits+1};}

export function shouldRequestReview(state:ReviewPromptState,now:number){
 if(state.requestCount>=REVIEW_REQUEST_LIMIT)return false;
 if(state.completedSpins<REVIEW_SPIN_THRESHOLD&&state.slotExits<REVIEW_SLOT_EXIT_THRESHOLD)return false;
 if(state.lastRequestAt&&now-state.lastRequestAt<REVIEW_COOLDOWN_MS)return false;
 if(state.lastAttemptAt&&now-state.lastAttemptAt<REVIEW_RETRY_MS)return false;
 return true;
}

export function finishedReviewAttempt(state:ReviewPromptState,now:number,launched:boolean):ReviewPromptState{
 return {...state,lastAttemptAt:now,requestCount:state.requestCount+(launched?1:0),lastRequestAt:launched?now:state.lastRequestAt};
}
