import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';import {BET_LEVELS} from './BetLevels';import {WOLF_LINES} from './WolfRules';import {SlotProgress,normalizeSlotProgress,socialPresentation,packRounds} from './Social2230Rules';
export const ATLAS_ID='golden-city-atlas';
const extra=Array.from({length:243},(_,i)=>{let code=i;return Array.from({length:5},(_,col)=>{const row=code%3;code=Math.floor(code/3);return row*5+col;});}).filter(line=>!WOLF_LINES.some(other=>other.every((c,i)=>c===line[i])));
export const ATLAS_LINES=[...WOLF_LINES,...extra.slice(0,15)];
export const ATLAS_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export interface AtlasMove {cell:number;region:number;before:number[];after:number[];completed:boolean;gain:'pick'|'multiplier'|null;award?:Win;}
export interface AtlasPlayback {stage:'map'|'treasure';before:number[];after:number[];moves:AtlasMove[];lineWins:Win[];picks?:Win[];multiplier?:number;}
export class GoldenAtlasSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=ATLAS_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;
 private progress:SlotProgress={};setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 readonly presentation=socialPresentation('네 도시 구역 · 선택권과 배수 적립','황금 도시 지도');
 readonly config:SlotConfig={id:ATLAS_ID,title:'황금 도시 지도첩',subtitle:'GOLDEN CITY ATLAS',tag:'REGION MAP COLLECTION',color:'#263e38',accent:'#e1c479',description:'5×3 · 40라인 · 왼쪽부터3개 이상\n지도 조각을 한 회전 최대7개 수집합니다.\n네 구역마다4조각. 구역 완성 때 소액 보상과 선택권 또는 배수+1.\n도시 전체를 완성하면 보물 경로 하나를 골라 적립한 횟수만큼 공개합니다.\n각 보물은 베팅1/2/4배 × 적립 배수.\n지역·선택권·배수는 베팅별 저장, 전체 보상 뒤 초기화.',symbols:['황금 피라미드','돌 나침반','옥색 석상','제단 그릇','갈고리 밧줄','탐험 수첩','가죽 장화','태양 메달','콘도르 WILD','지도 조각'].map((name,i)=>({id:ATLAS_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#e1c479',weight:[5,6,7,8,10,12,14,16,3,2][i],payout:i<8?ATLAS_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult {if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid atlas spin');const wins:Win[]=[];this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<8;s++){const cells:number[]=[];for(const c of line){if(board[c]!==ATLAS_ID+'-'+s&&board[c]!==ATLAS_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*ATLAS_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:ATLAS_ID+'-'+s,cells,amount};}if(best)wins.push(best);});return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};}
 resolve(board:string[],bet:number,rng:()=>number):SpinResult {
  const base=this.evaluate(board,bet),before=[...(this.progress[ATLAS_ID+':'+bet]||[0,0,0,0,1,1])],after=[...before],lineWins=[...base.wins],moves:AtlasMove[]=[];
  for(const cell of board.flatMap((s,i)=>s===ATLAS_ID+'-scatter'?[i]:[]).slice(0,7)){
   const available=[0,1,2,3].filter(i=>after[i]<4);if(!available.length)break;const region=available[Math.floor(rng()*available.length)],previous=[...after];after[region]++;const completed=after[region]===4;let gain:AtlasMove['gain']=null,award:Win|undefined;
   if(completed){gain=rng()<.5?'pick':'multiplier';after[gain==='pick'?4:5]++;award={line:-1,symbol:ATLAS_ID+'-scatter',cells:[cell],amount:Math.round(bet*[.5,1,1.5,2][Math.floor(rng()*4)])};base.wins.push(award);}
   moves.push({cell,region,before:previous,after:[...after],completed,gain,award});
  }
  base.payout=base.wins.reduce((n,w)=>n+w.amount,0);base.atlasFeature={stage:'map',before,after:[...after],moves,lineWins};base.progressUpdate={key:ATLAS_ID+':'+bet,values:[...after]};if(after.slice(0,4).some(n=>n<4))return base;
  const results=Array.from({length:3},()=>{const picks=Array.from({length:after[4]},()=>({line:-1,symbol:ATLAS_ID+'-0',cells:[],amount:bet*[1,2,4][Math.floor(rng()*3)]*after[5]})),reset=[0,0,0,0,1,1],prize:SpinResult={board:[...board],bet,wins:picks,payout:picks.reduce((n,w)=>n+w.amount,0),atlasFeature:{stage:'treasure',before:[...after],after:reset,moves:[],lineWins:[],picks,multiplier:after[5]}};return packRounds([base,prize],{featureOnly:true,progressUpdate:{key:ATLAS_ID+':'+bet,values:reset},presentation:this.presentation});});
  return{...results[0],featureChoices:{title:'황금 도시 완성 · 보물 경로 선택',labels:['피라미드 경로','신전 경로','수로 경로'],results,defaultIndex:0,noBonusEntry:true}};
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(Array.from({length:15},()=>this.pick(rng)),bet,rng);}
 demoSpin(bet:number){let seed=360928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<10000;i++){const r=this.spin(bet,rng);if(r.wins.length>0)return r;}throw Error('Atlas fixture unavailable');}
}
