export class BlackoutSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=BLACKOUT_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;readonly hasBonus=true;readonly bonusCalibrationKey=BLACKOUT_ID+':dual-blackout-v1';get bonusSymbol(){return BLACKOUT_ID+'-scatter';}get bonusTriggerCount(){return 5;}
 readonly presentation=socialPresentation('파랑·노랑 정전 · 실패한 진입에 번개 추가','전력 복구 무료 회전');
 readonly config:SlotConfig={id:BLACKOUT_ID,title:'정전 도시 복구반',subtitle:'BLACKOUT RESTORATION',tag:'DUAL BLACKOUT',color:'#233748',accent:'#eed57b',description:'5×3 · 60라인 · 왼쪽부터3개 이상\n파랑·노랑 번개 합계5개 이상: 무료8회. 6/7/8개 이상:12/20/30회.\n자연 진입 실패 시 번개가 있으면 각 색 정전이 독립적으로 추가 번개를 투입할 수 있습니다.\nWILD 위 번개는 두 역할 모두 유지. 노랑 번개는 다음 무료 회전부터 고정 WILD.\n무료 중 새 번개5개 이상 +3회, 총100회 상한. 구매 지급 별도 보정.',symbols:['안전모','공구상자','절연장갑','금속 스패너','변압기','전선 묶음','작업 전구','파랑 번개','발전기 WILD','노랑 번개'].map((name,i)=>({id:BLACKOUT_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#eed57b',weight:[5,6,8,10,12,14,16,1.8,2,1.8][i],payout:i<7?BLACKOUT_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult{if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid blackout board');const wins:Win[]=[];this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<7;s++){const cells:number[]=[];for(const c of line){if(board[c]!==BLACKOUT_ID+'-'+s&&board[c]!==BLACKOUT_ID+'-wild')break;cells.push(c);}if(cells.length>=3){const amount=Math.round(bet*BLACKOUT_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:BLACKOUT_ID+'-'+s,cells,amount};}}if(best)wins.push(best);});return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};}
 resolve(before:string[],bet:number,rng:()=>number,heldBefore:number[]=[],free=false):SpinResult{
  if(!this.bets.includes(bet)||before.length!==15||before.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid blackout board');const naturalBlue=before.flatMap((s,c)=>s===BLACKOUT_ID+'-7'?[c]:[]),naturalYellow=before.flatMap((s,c)=>s===BLACKOUT_ID+'-scatter'?[c]:[]),blue=[...naturalBlue],yellow=[...naturalYellow],after=[...before],injections:BlackoutInjection[]=[];
  if(!free&&blue.length+yellow.length>0&&blue.length+yellow.length<5){for(const color of ['blue','yellow'] as const){if(rng()>=.11)continue;const count=1+Math.floor(rng()*3),cells:number[]=[];for(let i=0;i<count;i++){const available=Array.from({length:15},(_,c)=>c).filter(c=>!blue.includes(c)&&!yellow.includes(c));if(!available.length)break;const cell=available[Math.floor(rng()*available.length)];cells.push(cell);(color==='blue'?blue:yellow).push(cell);if(after[cell]!==BLACKOUT_ID+'-wild')after[cell]=BLACKOUT_ID+(color==='blue'?'-7':'-scatter');}injections.push({color,cells});}}
  const r=this.evaluate(after,bet),heldAfter=Array.from(new Set([...heldBefore,...yellow]));r.heldAtStart=heldBefore.map(cell=>({cell,symbol:BLACKOUT_ID+'-wild',value:0}));r.blackoutFeature={before:[...before],after,naturalBlue,naturalYellow,blue,yellow,injections,heldBefore:[...heldBefore],heldAfter,free,lineWins:r.wins};return r;
 }
 private draw(bet:number,rng:()=>number,held:number[]=[],free=false){const board=Array.from({length:15},(_,c)=>held.includes(c)?BLACKOUT_ID+'-wild':this.pick(rng));return this.resolve(board,bet,rng,held,free);}
 private count(r:SpinResult){return r.blackoutFeature!.blue.length+r.blackoutFeature!.yellow.length;}
 private sequence(base:SpinResult,rng:()=>number):SpinResult{const n=this.count(base);if(n<5)return base;let remaining=n>=8?30:n===7?20:n===6?12:8,awarded=remaining,played=0,paid=base.payout,held=[...base.blackoutFeature!.yellow];const initial=remaining,rounds=[base];while(remaining>0&&paid<base.bet*this.maxWin){remaining--;played++;const r=this.draw(base.bet,rng,held,true);held=[...r.blackoutFeature!.heldAfter];let left=base.bet*this.maxWin-paid;for(const w of r.wins){w.amount=Math.min(w.amount,left);left-=w.amount;}r.payout=r.wins.reduce((s,w)=>s+w.amount,0);paid+=r.payout;const extra=this.count(r)>=5?Math.min(3,100-awarded):0;remaining+=extra;awarded+=extra;r.freeSpinsAdded=extra||undefined;r.freeSpinsRemaining=remaining;r.roundLabel='복구 무료 '+played+' · 남은 '+remaining+'회';rounds.push(r);}return packRounds(rounds,{freeSpinsAwarded:initial,featureName:'전력 복구 무료 회전',presentation:this.presentation,bonusEndReason:paid>=base.bet*this.maxWin?'max-win':'spins-exhausted'});}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.sequence(this.draw(bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{if(!this.bets.includes(bet))throw Error('Invalid bet');for(let i=0;i<100000;i++){const base=this.draw(bet,rng);if(this.count(base)<5)continue;const result=this.sequence(base,rng),rounds=result.rounds!.slice(1);return packRounds(rounds,{freeSpinsAwarded:result.freeSpinsAwarded,featureName:result.featureName,presentation:this.presentation,bonusEndReason:result.bonusEndReason,bonusTriggerRound:{board:[...base.board],bet,wins:[],payout:0,blackoutFeature:{...base.blackoutFeature!,lineWins:[]}}});}throw Error('Blackout conditional trigger unavailable');}
 demoSpin(bet:number){return this.find(bet,false);}bonusDemoSpin(bet:number){return this.find(bet,true);}private find(bet:number,bonus:boolean){let seed=390928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.payout>0)return r;}throw Error('Blackout fixture unavailable');}
}
