import {SlotConfig,SpinResult,Win} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
export const SOCIAL_1921_IDS=['vault-multiplier-workshop','neon-band-mixer','lantern-bridge'];
export const SOCIAL_1921_PAYS=[[.3,.8,2],[.25,.6,1.5],[.2,.5,1.2],[.15,.4,1],[.1,.3,.8],[.1,.25,.6],[.1,.2,.5],[.1,.2,.4]];
export function validateSocialBoard(config:SlotConfig,board:string[],bet:number,bets:readonly number[],size:number){
 if(!bets.includes(bet)||board.length!==size||board.some(id=>!config.symbols.some(s=>s.id===id)))throw Error('Invalid social spin: '+config.id);
}
export function social1921Pays(_id:string){return SOCIAL_1921_PAYS.map(row=>[...row]);}
export function lineAwards(id:string,board:string[],bet:number,multipliers:number[]=Array(25).fill(1)):Win[]{
 return WOLF_LINES.flatMap((line,index)=>{
  let best:Win|undefined;
  for(let symbol=0;symbol<8;symbol++){
   const cells:number[]=[];for(const cell of line){if(board[cell]!==id+'-'+symbol&&board[cell]!==id+'-wild')break;cells.push(cell);}
   if(cells.length<3)continue;
   const multiplier=social1921Pays(id)[symbol][cells.length-3]*multipliers[index],amount=Math.round(bet*multiplier);
   if(!best||amount>best.amount)best={line:index,symbol:id+'-'+symbol,cells,amount,multiplier};
  }
  return best?[best]:[];
 });
}
export function totalAwards(result:SpinResult){result.payout=result.wins.reduce((sum,w)=>sum+w.amount,0);return result;}
export const socialSeed=(initial:number)=>{let seed=initial;return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};};
