import {ExpansionSlot,expansionCells as cells,Geometry,randomIndex as ri} from './ExpansionCore';
import {drawThreeGateBoard} from './ConditionalGateBoard';
export class BuffaloDiamondSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);this.paylines.splice(9);this.config.symbols.push({id:this.id('diamond'),name:'Diamond Pot gem',color:'#69d9ed',weight:2,payout:0},{id:this.id('jackpot'),name:'Buffalo jackpot coin',color:'#f3cc76',weight:0,payout:0});}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-coins';}
 isWild(id:string){return id===this.id('wild')||id===this.id('jackpot');}
 private pool(col:number){return this.config.symbols.filter(s=>s.weight>0&&(col>=3||s.id!==this.id('wild')));}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 private stack(board:string[],rng:()=>number){const b=[...board];for(let col=0;col<5;col++){const first=[col,col+5,col+10].find(c=>b[c]===this.id(0));if(first===undefined||rng()>=.35)continue;const height=rng()<.7?2:3,start=Math.min(Math.floor(first/5),3-height);for(let row=start;row<start+height;row++){const c=row*5+col;if(this.config.symbols.slice(0,8).some(s=>s.id===b[c]))b[c]=this.id(0);}}return b;}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(!this.bets.includes(bet))throw Error('Invalid bet');const board:string[]=[];for(let c=0;c<g.columns*g.rows;c++){let pool=this.pool(c%5);if(board.some((s,i)=>i%5===c%5&&s===this.id('scatter')))pool=pool.filter(s=>s.id!==this.id('scatter'));board.push(this.weighted(rng,pool));}return this.stack(board,rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');const b=drawThreeGateBoard(col=>this.pool(col),this.id('scatter'),rng,(r,p)=>this.weighted(r,p));return this.purchaseFromResult(this.play(this.stack(b,rng),bet,rng));}
 private coinRound(input:string[],bet:number,rng:()=>number,free=false){
  const board=[...input];if(free)board.forEach((id,c)=>{if(c%5>=3&&id!==this.id('scatter')&&id!==this.id('diamond')&&rng()<.07)board[c]=this.id('wild');});board.forEach((id,c)=>{if(id===this.id('wild')&&c%5===4)board[c]=this.id('jackpot');});
  const values=board.map((s,c)=>s===this.id('wild')&&c%5===3?[2,3,5][ri(rng,3)]:0),hit=this.hit(board,bet,'9라인 · 4릴 코인 배수',this.geometry,{values,wildMode:'product'}),used=new Set(hit.wins.flatMap(w=>w.cells));
  const awards=cells(board,this.id('jackpot')).map(cell=>{const roll=rng(),tier=roll<.8?5:roll<.97?10:roll<.998?15:20;return{cell,win:this.prize(board,bet,tier,[cell],'5릴 코인 고정 잭팟').wins[0]};});
  const frames=[this.frame(board,'reels',free?'WILD RUSH · 코인 추가 등장':'버팔로 스택 · 코인 착지',[],{values,coinAwards:awards}),hit];hit.values=values;hit.coinAwards=awards;
  const paid=awards.filter(a=>used.has(a.cell));if(paid.length)frames.push(this.frame(board,'win','당첨에 참여한 5릴 코인 · 한 번 지급',paid.map(a=>a.cell),{values,coinAwards:awards,wins:paid.map(a=>a.win)}));
  const gems=cells(board,this.id('diamond'));if(gems.length>=4){const tier=[5,10,15,20][Math.min(3,gems.length-4)];frames.push(this.frame(board,'collect','다이아 4개 이상 · 별도 항아리',gems,{values,coinAwards:awards,meter:{label:'DIAMOND POT',before:0,after:gems.length,target:4,items:gems.map(cell=>({cell,value:1}))}}),this.prize(board,bet,tier,gems,'다이아 항아리 · 한 번 지급'));}
  for(const f of frames)if(f.coinAwards)f.coinAwards=awards;
  for(const f of frames)f.panel={label:'DIAMOND POT',values:[f.caption==='다이아 항아리 · 한 번 지급'?gems.length:0],columns:1};
  return this.round(bet,frames);
 }
 play(board:string[],bet:number,rng:()=>number){const base=this.coinRound(board,bet,rng),gates=cells(board,this.id('scatter'));if(new Set(gates.map(c=>c%5)).size<3)return this.finish([base]);return this.freeFromRound(base,bet,rng,5,b=>this.coinRound(b,bet,rng,true),gates);}
}
