    if(season===2)for(const c of wilds){let to=c;while(to+8<64){after[to]='';changed.push(to);to+=8;}after[to]=this.seasonWild(season);changed.push(to);if(to!==c)moves.push({from:c,to,symbol:this.seasonWild(season)});}
