   frames.push(this.frame(board,'collect',fresh?'새 조각 → 퍼즐 칸 '+(piece+1):'이미 모은 조각 · 진행 유지',[cell],{panel:{...panel(before),active:[piece]},joeyPuzzle:step(before,'piece',{piece,fresh}),meter:{label:'퍼즐 '+(puzzle+1),before:count(before),after:count(state[0]),target:9,items:[{cell,value:fresh?1:0}]}},g));
   frames.push(this.frame(board,'state','퍼즐 '+count(state[0])+'/9 확인',[],{panel:{...panel(state[0]),active:[piece]},joeyPuzzle:step(state[0],'confirmed',{piece,fresh})},g));
