import {ExpansionSlot,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';

/** The Dog House provider help: line-bet pays, divided by 20 total-bet lines.
 * Symbol/reel weights and 3x3 number probabilities are our local model. */
export const DOG_LINE_PAYS=[
 [50,150,750],[35,100,500],[25,60,300],[20,40,200],
 [8,20,100],[12,25,150],[5,10,50],[5,10,50],
 [2,5,25],[2,5,25],[2,5,25],
] as const;
/** Fixed local reel weights derived from the line/feature expectation, not an award multiplier. */
export const DOG_MODEL={"baseHigh":4.171992999036094,"baseScatter":8.260517309196391,"freeWild":2.425024160655176};
export class DogYardSlot extends ExpansionSlot {
 get bonusCalibrationKey(){return this.config.id+':dog-rules-v2';}
 constructor(spec:ExpansionSlot['spec']){
  super(spec);
  this.config.description='slot.dog.rules';
  const regular=this.config.symbols.slice(0,6),ranks=['A','K','Q','J','10'];
  for(let i=0;i<5;i++)regular.push({id:this.id(i+6),name:ranks[i],color:'#efd08c',weight:14,payout:0});
  this.config.symbols=[...regular,...this.config.symbols.slice(8)];
  regular.forEach((symbol,index)=>symbol.payout=this.unit(index,5));
  this.config.symbols.find(symbol=>symbol.id===this.id('scatter'))!.weight=DOG_MODEL.baseScatter;
 }
 unit(symbol:number,count:number){return count>=3&&count<=5?(DOG_LINE_PAYS[symbol]?.[count-3]||0)/20:0;}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry,free=false):string[]{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const board:string[]=[];
  for(let cell=0;cell<g.columns*g.rows;cell++){
   const col=cell%5,pool=this.config.symbols.filter(s=>s.weight>0&&
    (s.id!==this.id('wild')||col>0&&col<4)&&
    (s.id!==this.id('scatter')||!free&&col%2===0&&!board.some((id,c)=>c%5===col&&id===s.id))).map(s=>({...s,weight:s.id===this.id('wild')&&free?DOG_MODEL.freeWild:s.id===this.id(0)&&!free?s.weight*DOG_MODEL.baseHigh:s.id===this.id('scatter')?DOG_MODEL.baseScatter:s.weight}));
   let roll=rng()*pool.reduce((sum,s)=>sum+s.weight,0),symbol=pool.at(-1)!.id;
   for(const candidate of pool){roll-=candidate.weight;if(roll<0){symbol=candidate.id;break;}}board.push(symbol);
  }return board;
 }
 evaluate(board:string[],bet:number,g:Geometry=this.geometry,opts:Parameters<ExpansionSlot['evaluate']>[3]={}):SpinResult{
  this.validate(board,bet,g);const wins:Win[]=[];
  for(const [line,path] of this.paylines.entries()){
   let best:Win|undefined;
   for(let symbol=0;symbol<DOG_LINE_PAYS.length;symbol++){
    const found:number[]=[];
    for(const cell of path){if(board[cell]!==this.id(symbol)&&board[cell]!==this.id('wild'))break;found.push(cell);}
    if(found.length<3)continue;
    const multiplier=found.filter(cell=>board[cell]===this.id('wild')).reduce((sum,cell)=>sum+(opts.values?.[cell]||1),0)||1;
    const multiple=this.unit(symbol,found.length)*multiplier,amount=Math.round(bet*multiple);
    if(amount>0&&(!best||amount>best.amount))best={line,symbol:this.id(symbol),cells:found,amount,multiplier:multiple};
   }if(best)wins.push(best);
  }
  return{board:[...board],bet,wins,payout:wins.reduce((sum,w)=>sum+w.amount,0),presentation:this.presentation};
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  // Condition only on the three independent qualifying reels, never on payout.
  if(!this.bets.includes(bet))throw Error('Invalid bet');const board=Array<string>(15);
  for(let col=0;col<5;col++){
   const pool=this.config.symbols.filter(s=>s.weight>0&&(s.id!==this.id('wild')||col>0&&col<4)).map(s=>({...s,weight:s.id===this.id(0)?s.weight*DOG_MODEL.baseHigh:s.id===this.id('scatter')?DOG_MODEL.baseScatter:s.weight})),plain=pool.filter(s=>s.id!==this.id('scatter'));
   let gate=-1;
   if(col%2===0){const q=1-pool.find(s=>s.id===this.id('scatter'))!.weight/pool.reduce((sum,s)=>sum+s.weight,0);let roll=rng()*(1+q+q*q);gate=2;for(let row=0;row<3;row++){roll-=q**row;if(roll<0){gate=row;break;}}}
   for(let row=0;row<3;row++){
    let symbol=this.id('scatter');
    if(row!==gate){let roll=rng()*plain.reduce((sum,s)=>sum+s.weight,0);symbol=plain.at(-1)!.id;for(const candidate of plain){roll-=candidate.weight;if(roll<0){symbol=candidate.id;break;}}}
    board[row*5+col]=symbol;
   }
  }
  return this.purchaseFromResult(this.play(board,bet,rng));
 }
 play(board:string[],bet:number,rng:()=>number){
  this.validate(board,bet);
  const reelMultipliers=Array.from({length:5},()=>2+randomIndex(rng,2));
  const opening=board.map((id,cell)=>id===this.id('wild')?reelMultipliers[cell%5]:0),wilds=cells(board,this.id('wild'));
  const frames=[this.frame(board,'reels','slot.dog.land',[],{values:opening})];
  if(wilds.length)frames.push(this.frame(board,'trigger','slot.dog.wild',wilds,{values:opening}));
  frames.push(this.hit(board,bet,'slot.dog.pay',this.geometry,{values:opening}));
  const gates=cells(board,this.id('scatter')),qualified=[0,2,4].every(col=>gates.some(cell=>cell%5===col));
  const normal=this.round(bet,frames);if(!qualified)return this.finish([normal]);
  const scatter=this.prize(board,bet,5,gates,'slot.dog.scatter');scatter.wins[0].symbol=this.id('scatter');frames.push(scatter);
  // Each number is disclosed independently. The panel stores only revealed values.
  const numbers=Array.from({length:9},()=>1+randomIndex(rng,3)),awarded=numbers.reduce((sum,n)=>sum+n,0),shown=Array(9).fill(0);
  frames.push(this.frame(board,'trigger','slot.dog.entry',gates,{panel:{label:'slot.dog.freeGrid',values:[...shown],columns:3}}));
  for(let index=0;index<9;index++){
   shown[index]=numbers[index];frames.push(this.frame(board,'reveal','slot.dog.entry',[],{panel:{label:'slot.dog.freeGrid',values:[...shown],columns:3,active:[index]}}));
  }
  frames.push(this.frame(board,'state','slot.dog.entryTotal',[],{panel:{label:'slot.dog.freeTotal',values:[awarded],columns:1}}));
  const rounds=[normal],held=new Map<number,number>();
  for(let left=awarded-1;left>=0;left--){
   const b=this.draw(bet,rng,this.geometry,true),prior=Array.from(held.keys()),values=b.map(id=>id===this.id('wild')?2+randomIndex(rng,2):0);
   held.forEach((value,cell)=>{b[cell]=this.id('wild');values[cell]=value;});
   const landed=cells(b,this.id('wild')).filter(cell=>!held.has(cell));
   const freeFrames=[this.frame(b,'reels','slot.dog.freeLand',[],{held:prior,values})];
   if(landed.length)freeFrames.push(this.frame(b,'trigger','slot.dog.wild',landed,{held:prior,values}));
   landed.forEach(cell=>held.set(cell,values[cell]));
   if(landed.length)freeFrames.push(this.frame(b,'effect','slot.dog.lock',landed,{held:Array.from(held.keys()),values}));
   freeFrames.push(this.hit(b,bet,'slot.dog.pay',this.geometry,{values}));
   rounds.push(this.round(bet,freeFrames,{heldAtStart:prior.map(cell=>({cell,symbol:this.id('wild'),value:values[cell]})),freeSpinsRemaining:left}));
  }
  return this.finish(rounds,{freeSpinsAwarded:awarded,featureOnly:false});
 }
}
