export function consentParagraphs(body:string):string[]{return body.split(/\n\s*\n/g).map(paragraph=>paragraph.trim()).filter(Boolean);}
export function parseConsent(value:string|null):ConsentReceipt|null{
 try{const receipt=JSON.parse(value||'null');return receipt?.version===CONSENT_VERSION&&receipt.terms===true&&receipt.privacy===true&&Number.isSafeInteger(receipt.acceptedAt)&&receipt.acceptedAt>0?receipt:null;}catch{return null;}
}
export function consentReceipt(now=Date.now()):ConsentReceipt{return{version:CONSENT_VERSION,acceptedAt:now,terms:true,privacy:true};}
