/** Tracks real requests only; never sends connectivity probes. */
export class NetworkWait {
 private pending=new Map<object,number>();
 constructor(private now=()=>Date.now()){}
 async track<T>(request:()=>Promise<T>):Promise<T>{
  const id={};this.pending.set(id,this.now());
  try{return await request();}finally{this.pending.delete(id);}
 }
 get delayed(){const now=this.now();return [...this.pending.values()].some(start=>now-start>=10000);}
}
export const networkWait=new NetworkWait();
