import {FeatureGame,Random,choose,sampleCells} from './FeatureKit';
import {featureDefinitions} from './FeatureDefinitions';
import {SpinResult,Win,Cascade} from './SlotMain';
export class SushiPartySlot extends FeatureGame {
 readonly columns=8;readonly mode='clusters' as const;readonly clusterPays=[.1,.15,.2,.3,.5,1,2,5];
 get bonusSymbol(){return this.wildSymbol;}
 constructor(){super(featureDefinitions['sushi-party']);}
 evaluate(board:string[],bet:number,values:number[]=Array(64).fill(1)):SpinResult {
  if(board.length!==64||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid sushi board');const wins:Win[]=[];
  for(let s=0;s<8;s++){const symbol=this.config.symbols[s].id,seen=new Set<number>();
   for(let start=0;start<64;start++){if(board[start]!==symbol||seen.has(start))continue;const cells:number[]=[],queue=[start];seen.add(start);
    while(queue.length){const at=queue.pop()!;cells.push(at);for(const next of [at-8,at+8,...(at%8?[at-1]:[]),...(at%8<7?[at+1]:[])])if(next>=0&&next<64&&!seen.has(next)&&(board[next]===symbol||board[next]===this.wildSymbol)){seen.add(next);queue.push(next);}}
    if(cells.length>=5){const multiplier=Math.max(1,cells.filter(i=>board[i]===this.wildSymbol).reduce((n,i)=>n+values[i],0));wins.push({line:-1,symbol,cells,multiplier,amount:Math.round(bet*this.definition.topPays[s]*this.clusterPays[Math.min(7,cells.length-5)]*multiplier)});}
   }
  }return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0)};
 }
 spin(bet:number,rng:Random=Math.random):SpinResult {
  if(!this.bets.includes(bet))throw Error('Invalid bet');let held=new Map<number,number>();
  const roll=(free=false):SpinResult=>{
   let board=this.rollBoard(rng),values=Array(64).fill(0);if(free)held.forEach((v,i)=>{board[i]=this.wildSymbol;values[i]=v;});
   if(!free){const count=rng()<.018?3:rng()<.22?1:0;for(const i of sampleCells(64,count,rng)){board[i]=this.wildSymbol;values[i]=1;}}
   if(rng()<.06){const side=choose([2,3],rng),x=Math.floor(rng()*(9-side)),y=Math.floor(rng()*(9-side)),symbol=this.pick(rng);for(let row=0;row<side;row++)for(let col=0;col<side;col++){const i=(y+row)*8+x+col;if(board[i]!==this.wildSymbol)board[i]=symbol;}}
   const cascades:Cascade[]=[],wins:Win[]=[];
   for(let step=0;step<40;step++){
    const r=this.evaluate(board,bet,values),removed=Array.from(new Set(r.wins.flatMap(w=>w.cells))).filter(i=>board[i]!==this.wildSymbol),before=[...values];
    const winningWilds=new Set(r.wins.flatMap(w=>w.cells).filter(i=>board[i]===this.wildSymbol));winningWilds.forEach(i=>values[i]++);
    const stage:Cascade={board:[...board],wins:r.wins,payout:r.payout,multiplier:1,cellMultipliers:before,nextMultipliers:[...values],drops:[],removedCells:removed};cascades.push(stage);wins.push(...r.wins);if(!removed.length||step===39)break;
    const gone=new Set(removed),next=Array<string>(64),nextValues=Array(64).fill(0);
    for(let c=0;c<8;c++){const keep=Array.from({length:8},(_,row)=>row*8+c).filter(i=>!gone.has(i)),incoming=8-keep.length;for(let row=0;row<8;row++){const to=row*8+c,from=row<incoming?(row-incoming)*8+c:keep[row-incoming],symbol=from<0?this.pick(rng):board[from];next[to]=symbol;nextValues[to]=from<0?0:values[from];stage.drops.push({to,from,symbol});}}
    // A winning cat trades places with one adjacent surviving symbol; identities are preserved.
    for(const origin of Array.from(winningWilds)){const a=stage.drops.find(d=>d.from===origin)!;const adjacent=stage.drops.filter(d=>d.from>=0&&d.symbol!==this.wildSymbol&&Math.abs(d.to%8-a.to%8)+Math.abs(Math.floor(d.to/8)-Math.floor(a.to/8))===1);if(!adjacent.length)continue;const b=choose(adjacent,rng),at=a.to,bt=b.to;a.to=bt;b.to=at;[next[at],next[bt]]=[next[bt],next[at]];[nextValues[at],nextValues[bt]]=[nextValues[bt],nextValues[at]];}
    stage.nextMultipliers=[...nextValues];board=next;values=nextValues;
   }
   held=new Map(board.map((id,i)=>[i,id===this.wildSymbol?values[i]:0] as [number,number]).filter(pair=>pair[1]>0));
   return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades,symbolValues:values,featureText:'이동 고양이 · 당첨마다 배수 +1'};
  };
  const base=roll(),rounds=[base];if(held.size<3)return this.finish(rounds,'');for(let i=0;i<8;i++){const r=roll(true);r.roundLabel='초밥 잔치 '+(i+1)+'/8';rounds.push(r);}return this.finish(rounds,'초밥 잔치',8);
 }
}
