import {tomeRound,TomeRound} from './TomeFeature';
import {tomeSequenceResult,tomeResult} from './TomeResult';
import {TOME_MODEL} from './TomeMath';
import type {SpinResult} from './SlotMain';

/** Our own sampling weights; the source game's private reel math is not public.
 * These are provisional until independent distribution/purchase calibration.
 * 0..7 regular,8 book,9 portrait. Mega is awarded by the eye feature only. */
export const TOME_WEIGHTS=[5,6,7,8,12,14,16,18,.4,.2] as const;
export function tomeSampler(rng:()=>number,free=false){
 const weights=TOME_WEIGHTS.map((w,i)=>w*((free?i===0:i<4)?(free?TOME_MODEL.freeHigh:TOME_MODEL.baseHigh):i===7?(free?1:TOME_MODEL.baseLow):i>=8?(free?TOME_MODEL.freeWild:TOME_MODEL.baseWild):1)),sum=weights.reduce((a,b)=>a+b,0);
 const roll=()=>{const n=rng();if(!Number.isFinite(n)||n<0||n>=1)throw Error('Invalid Tome RNG');return n;};
 const pick=()=>{let n=roll()*sum;for(let i=0;i<TOME_WEIGHTS.length;i++){n-=weights[i];if(n<0)return i;}return 9;};
 const eyes=(count:number)=>{const cells=Array.from({length:25},(_,i)=>i),chosen:number[]=[];for(let i=0;i<count;i++){const index=Math.floor(roll()*cells.length);chosen.push(cells.splice(index,1)[0]);}return chosen.sort((a,b)=>a-b);};
 return{roll,pick,eyes,board:()=>Array.from({length:25},pick)};
}
/** One natural wager, one state-generated base sequence and at most one Other
 * World. Remaining max-win budget is shared, never reset on bonus entry. */
export function tomeGame(bet:number,rng:()=>number=Math.random,opening?:number[]):SpinResult{
 const sample=tomeSampler(rng),limit=bet*2000;
 const base=tomeRound({board:opening??sample.board(),bet,mode:'base',eyes:sample.roll()<.12?sample.eyes(1):[],pick:sample.pick,rng:sample.roll,limit});
 let bonus:TomeRound|undefined;
 if(base.effectsAwarded&&base.payout<limit){
  bonus=tomeOtherWorld(bet,rng,base.effectsAwarded,limit-base.payout);
 }
 return tomeSequenceResult('tome-of-madness',bet,base,bonus);
}

/** Same source feature for natural entries and direct purchases. Only the
 * private input distribution differs from the base game. */
export function tomeOtherWorld(bet:number,rng:()=>number,effects=3,limit=bet*2000):TomeRound{
 const sample=tomeSampler(rng,true);
 return tomeRound({board:sample.board(),bet,mode:'other-world',eyes:sample.eyes(sample.roll()<.5?11:12),effects,pick:sample.pick,rng:sample.roll,limit});
}
export function tomePurchase(bet:number,rng:()=>number):SpinResult{
 // A purchase opens a fully charged portal. It does not find or pay a base
 // cascade, and it uses the minimum legal entry of three portal effects.
 const sample=tomeSampler(rng),board=sample.board();
 const trigger=tomeResult('tome-of-madness',bet,{mode:'base',opening:board,board,eyes:[],opened:[],stages:[],payout:0,charge:42,effectsAwarded:3});
 trigger.roundLabel='BONUS TRIGGER';
 const free=tomeResult('tome-of-madness',bet,tomeOtherWorld(bet,rng));
 return {...free,rounds:[free],bonusTriggerRound:trigger,freeSpinsAwarded:1,featureName:'이세계 · 포털 효과 3개'};
}
