import {vikingOrdinaryCascade} from './VikingCascade';
import {VikingProgress} from './VikingProgress';
import {vikingExecuteDestruction,VikingDestructionPlan,VikingRagnarokEvent} from './VikingRagnarok';

/** Connect a base cascade to its one charge effect and all resulting cascades.
 * Ragnarok is a boundary, never a settled payable round. God-gift selection,
 * Ragnarok entry generation, Valhalla and final settlement are upstream/downstream.
 * Provider visual Ragnarok help requires20 ADDITIONAL winning symbols after
 * the destruction, so the second meter starts at zero.
 */
export function vikingChargeRound(initial:readonly number[],bet:number,hooks:{
 refill:(column:number,row:number)=>number;
 plan:(board:readonly number[])=>VikingDestructionPlan;
},state:{progress?:VikingProgress;maxCascadeSteps?:number}={}){
 const first=vikingOrdinaryCascade(initial,bet,hooks.refill,{progress:state.progress,maxSteps:state.maxCascadeSteps});
 const events:VikingRagnarokEvent[]=[{kind:'cascades',segment:first}];
 if(first.next!=='charge-effect')return {events,board:[...first.board],subtotal:first.subtotal,progress:first.progress,charge:first.charge,next:first.next,effectPlayed:false};
 const effect=vikingExecuteDestruction(first.board,hooks.plan([...first.board]),hooks.refill);
 events.push({kind:'destruction',effect});
 const last=vikingOrdinaryCascade(effect.after,bet,hooks.refill,{charge:0,subtotal:first.subtotal,progress:first.progress,effectPlayed:true,maxSteps:state.maxCascadeSteps});
 events.push({kind:'cascades',segment:last});
 return {events,board:[...last.board],subtotal:last.subtotal,progress:last.progress,charge:last.charge,next:last.next,effectPlayed:true};
}
