import {SlotMain,SlotConfig,SlotPresentation} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {LEGACY_LINES,LEGACY_LINE_PAYS} from './LegacyRules';
import {legacyRound} from './LegacyFeature';
import {legacyResult,legacySymbol} from './LegacyResult';
import {legacyGame,legacySampler} from './LegacyGame';

/** Dedicated engine; registered after isolated math and actual playback QA. */
export class LegacySlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;
 readonly bets=[...BET_LEVELS];readonly paylines=LEGACY_LINES;readonly hasBonus=true;
 get bonusSymbol(){return 'legacy-of-wildead-scatter';}get bonusTriggerCount(){return 3;}readonly maxWin=5000;
 get unlockPriceTenths(){return 1000;}
 readonly usesReferencePayouts=true;readonly bonusCalibrationKey='legacy-of-wildead:expansions';
 readonly rules=['5×3 · 10라인 · 일반 배당은 총베팅/10 기준','제단은 WILD·SCATTER · 3/4/5개는 총베팅2/20/200배','스캐터3개 이상 → 8프리스핀과 확장심볼1종','재진입 → +8회와 확장심볼 추가 · 기존 선택 유지','선택심볼은 필요한 수의 릴에 나오면 릴 전체 확장 · 사이 빈 릴 허용'];
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'제단이 열립니다',triggerText:'무덤의 문 · 프리스핀',bonusInText:'확장 심볼 선택 · 8회',hitText:'선택 심볼 · 릴 확장',totalWinText:'모래의 기억 · 총 당첨',signature:'재진입마다 확장 심볼 추가 · +8회',uiEffect:'제단 개방 · 선택목록 유지 · 심볼별 순차 확장',soundCue:'featureLand',anticipationHold:.35,hitHold:.2,outHold:.6};
 readonly config:SlotConfig={id:'legacy-of-wildead',title:'모래의 기억',subtitle:'DUNES OF MEMORY',tag:'MULTI EXPANDING',color:'#40332b',accent:'#dbbd7d',description:'제단3개부터 8프리스핀\n선택 심볼은 릴을 가득 채워 지급\n재진입마다 +8회와 확장 심볼 추가',symbols:[
  ...['미라왕','자칼 수호자','파라오 가면','날개 편 매','A','K','Q','J','10'].map((name,index)=>({id:legacySymbol('legacy-of-wildead',index),name,art:index<4?['boy','cat','mask','bird'][index]:'tower',color:'#eaca82',weight:1,payout:LEGACY_LINE_PAYS[index][4]/10})),
  {id:'legacy-of-wildead-scatter',name:'제단 · WILD / SCATTER',art:'tower',color:'#eaca82',weight:0,payout:0},
 ]};
 private present(result:ReturnType<typeof legacyGame>){result.presentation=this.presentation;result.rounds?.forEach(r=>r.presentation=this.presentation);return result;}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid Legacy bet');return this.present(legacyGame(bet,rng));}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid Legacy bet');
  const sample=legacySampler(rng),opening=Array.from({length:15},sample.pick),reels=[0,1,2,3,4];
  for(let hit=0;hit<3;hit++){const col=reels.splice(Math.floor(sample.roll()*reels.length),1)[0];opening[Math.floor(sample.roll()*3)*5+col]=9;}
  return this.present(legacyGame(bet,rng,{opening,purchase:true}));
 }
 evaluate(board:string[],bet:number){if(!this.bets.includes(bet))throw Error('Invalid Legacy bet');return this.present(legacyResult(this.config.id,bet,legacyRound(board.map(id=>this.config.symbols.findIndex(s=>s.id===id)),bet)));}
 demoSpin(bet:number){return this.evaluate([1,1,6,7,1,5,2,8,3,6,4,7,5,8,2].map(n=>legacySymbol(this.config.id,n)),bet);}
 bonusDemoSpin(bet:number){
  // Includes a real 3-altar entry, a retrigger and multiple expanding types.
  const ordinary=[1,4,6,7,1,5,2,8,3,6,4,7,5,8,2],trigger=[...ordinary];for(const cell of [0,6,12])trigger[cell]=9;
  return this.present(legacyGame(bet,()=>.2,{board:index=>[...(index===0||index===2?trigger:ordinary)]}));
 }
}
