export const POCKET_SETTLEMENT_HEIGHT=92;
// Collection overlays the reel/WIN seam and never reserves a permanent lane.
export const POCKET_SETTLEMENT_SPACE=0;
export function pocketSettlementSpace(_slotId:string){return 0;}

export function pocketSettlementFrame(win:{x:number;y:number;width:number}){
 const width=Math.min(432,win.width-32);
 return {x:win.x+(win.width-width)/2,y:win.y-POCKET_SETTLEMENT_HEIGHT*.62,width,height:POCKET_SETTLEMENT_HEIGHT};
}
