import {ExpansionSlot,ExpansionFrame,expansionCells as cells} from './ExpansionCore';
export class FelineDoubleSlot extends ExpansionSlot {
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-paws';}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 prepareBonusPurchase(bet:number,rng:()=>number){
  // Each reel has zero, one or two effective paws. Enumerate its exact
  // 3^5 distribution conditioned on >=5, rather than rejecting whole spins.
  const pool=this.config.symbols.filter(s=>s.weight>0),plain=pool.filter(s=>s.id!==this.id('scatter')),p=pool.find(s=>s.id===this.id('scatter'))!.weight/pool.reduce((n,s)=>n+s.weight,0),q=1-p,no=q*q*q,prob=[no,(1-no)*.82,(1-no)*.18],states:{counts:number[];weight:number}[]=[];
  for(let code=0;code<243;code++){let x=code,weight=1;const counts=Array.from({length:5},()=>{const n=x%3;x=Math.floor(x/3);weight*=prob[n];return n;});if(counts.reduce((n,v)=>n+v,0)>=5)states.push({counts,weight});}
  let roll=rng()*states.reduce((n,s)=>n+s.weight,0),chosen=states[states.length-1];for(const state of states){roll-=state.weight;if(roll<0){chosen=state;break;}}
  const board=Array.from({length:15},()=>this.weighted(rng,plain)),forced=Array(15).fill(0);
  chosen.counts.forEach((count,col)=>{if(!count)return;let roll=rng()*(1+q+q*q),row=2;for(let r=0;r<3;r++){roll-=Math.pow(q,r);if(roll<0){row=r;break;}}const cell=row*5+col;board[cell]=this.id('scatter');forced[cell]=count;});
  return this.purchaseFromResult(this.play(board,bet,rng,forced));
 }
 play(board:string[],bet:number,rng:()=>number,forced?:number[]){
  const feline=(b:string[],initial?:number[])=>{const split=b.map((s,c)=>initial?.[c]|| (s===this.id('wild')?2:(s===this.id('scatter')||this.config.symbols.slice(0,5).some(t=>t.id===s))&&rng()<.18?2:1)),double=split.flatMap((v,c)=>v===2?[c]:[]),fs=[this.frame(b,'reels','고양이 착지'),this.frame(b,'trigger','한 칸의 두 마리 · 실제 심볼 2개',double),this.hit(b,bet,'Split Symbol · 30라인 당첨',this.geometry,{split,splitWildForCats:true})];fs.forEach(f=>f.values=[...split]);return{split,fs};};
  const {split,fs}=feline(board,forced),paws=cells(board,this.id('scatter')),count=paws.reduce((n,c)=>n+split[c],0),base=this.round(bet,fs);
  if(count===4){const prize=this.prize(board,bet,2,paws,'발바닥 별도 보상');prize.wins.forEach(w=>{w.amount=bet*2;w.multiplier=2;w.symbol=this.id('scatter');});fs.push(this.frame(board,'trigger','발바닥 4개 · 2배 보상',paws,{values:[...split]}),prize);prize.values=[...split];}
  if(count<5)return this.finish([base]);fs.push(this.frame(board,'trigger','발바닥 '+count+'개 · 무료 10회',paws,{values:[...split]}));const rounds=[base];
  for(let left=9;left>=0;left--)rounds.push(this.round(bet,feline(this.draw(bet,rng)).fs,{freeSpinsRemaining:left}));return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});
 }
}
