import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {WOLF_LINES} from './WolfRules';
import {awardLines,packRounds,socialPresentation} from './Social2230Rules';
export const BRONZE_ID='bronze-guard-march';
export const GUARD=BRONZE_ID+'-guard';
export const BRONZE_SCATTER=BRONZE_ID+'-scatter';
export const BRONZE_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export interface BronzeMarch {before:string[];shifted:string[];moves:{from:number;to:number}[];newCells:number[];remaining:number;collected:number;terminal:boolean;prize?:Win;rewardReel?:{values:number[];selected:number};}
export type BronzeResult=SpinResult&{bronzeFeature?:BronzeMarch};
/** Local single-board adaptation: the bottom guard exits to the parade tally.
 * Published Aquila describes vertical nudges but not edge/value mathematics.
 * All values, 25 line paths, 100-respin ceiling and edge rule are our design. */
export class BronzeGuardSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly maxWin=10000;readonly usesLocalPayouts=true;readonly hasBonus=true;
 readonly bonusCalibrationKey=BRONZE_ID+':sculpture-v1';get bonusSymbol(){return BRONZE_SCATTER;}
 readonly presentation=socialPresentation('수호대 릴 한 칸 하강','청동 수호대 행진');
 readonly config:SlotConfig={id:BRONZE_ID,title:'청동 수호대 행진',subtitle:'BRONZE GUARD MARCH',tag:'VERTICAL GUARD RESPINS',color:'#313b42',accent:'#e4bd7c',description:'5×3 · 25라인 · 왼쪽부터 3개 이상\n수호대 6개 이상: 리스핀 3회. 새 수호대 착지 시 3회로 복구.\n위쪽 두 칸에 수호대가 있는 릴의 수호대가 다음 회전에 한 칸 내려갑니다.\n화면을 나간 수호대도 행진 합계에 보존합니다. 모은 수호대당 베팅의 0.25배.\n모든 칸이 수호대면 단일 보상 릴에서 ×2/3/5를 정해 합계에 적용.\n석상 3/4/5개: 무료 6/10/100회. 무료 중 하위 2종 제외.\n무료 총100회, 행진 최대100회. 표기 규칙은 자체 각색입니다.',symbols:['청동 투구','붉은 방패','은빛 창끝','청동 나팔','가죽 군화','자주 군기','봉인 두루마리','성문 열쇠','수호대 방패','흰 석상'].map((name,n)=>({id:BRONZE_ID+'-'+(n===8?'guard':n===9?'scatter':n),name,color:'#e4bd7c',weight:[5,6,7,8,10,12,14,16,7,1.7][n],payout:n<8?BRONZE_PAYS[n][2]:0}))};
 private validate(board:string[],bet:number){if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid bronze board');}
 evaluate(board:string[],bet:number):BronzeResult{this.validate(board,bet);const wins=awardLines(this.config,board,bet,BRONZE_PAYS);return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};}
 private drawBoard(rng:()=>number,free=false):string[]{
  const available=this.config.symbols.filter((_,i)=>!free||i!==6&&i!==7),total=available.reduce((n,s)=>n+s.weight,0);
  const board=Array.from({length:15},()=>{let n=rng()*total;for(const s of available){n-=s.weight;if(n<0)return s.id;}return available[available.length-1].id;});
  // At most one sculpture per reel; sample regular replacement, not a fixed winning board.
  for(let c=0;c<5;c++){let seen=false;for(let row=0;row<3;row++){const i=row*5+c;if(board[i]===BRONZE_SCATTER){if(seen)board[i]=available[Math.min(7,Math.floor(rng()*8))% (free?6:8)].id;seen=true;}}}
  return board;
 }
 private draw(bet:number,rng:()=>number,free=false):BronzeResult{return this.evaluate(this.drawBoard(rng,free),bet);}
 march(base:BronzeResult,rng:()=>number):BronzeResult[]{
  let board=[...base.board],collected=board.filter(s=>s===GUARD).length;if(collected<6)return[];
  const rounds:BronzeResult[]=[];let remaining=3;
  if(collected===15){const multiple=[2,3,5][Math.min(2,Math.floor(rng()*3))],prize:Win={line:-1,symbol:GUARD,cells:Array.from({length:15},(_,i)=>i),amount:Math.round(base.bet*.25*15*multiple),multiplier:multiple};return[{board:[...board],bet:base.bet,wins:[prize],payout:prize.amount,heldAtStart:board.map((symbol,cell)=>({cell,symbol,value:0})),bronzeFeature:{before:[...board],shifted:[...board],moves:[],newCells:[],remaining:0,collected:15,terminal:true,prize,rewardReel:{values:[2,3,5],selected:multiple}}}];}
  for(let step=0;remaining>0&&step<100;step++){
   const before=[...board],shifted=[...board],moves:{from:number;to:number}[]=[];
   for(let c=0;c<5;c++)if(before[c]===GUARD||before[5+c]===GUARD){
    for(let row=0;row<3;row++)shifted[row*5+c]=BRONZE_ID+'-7';
    for(let row=0;row<3;row++)if(before[row*5+c]===GUARD){const from=row*5+c,to=row===2?-1:from+5;moves.push({from,to});if(to>=0)shifted[to]=GUARD;}
   }
   board=[...shifted];const newCells:number[]=[];remaining--;
   for(let i=0;i<15;i++)if(board[i]!==GUARD){if(rng()<.10){board[i]=GUARD;newCells.push(i);}else board[i]=BRONZE_ID+'-'+Math.floor(rng()*8);}
   collected+=newCells.length;if(newCells.length)remaining=3;
   const full=board.every(s=>s===GUARD),terminal=full||remaining===0||step===99;
   let prize:Win|undefined,rewardReel:BronzeMarch['rewardReel'];if(terminal){const multiple=full?[2,3,5][Math.min(2,Math.floor(rng()*3))]:1;prize={line:-1,symbol:GUARD,cells:board.flatMap((s,i)=>s===GUARD?[i]:[]),amount:Math.min(base.bet*this.maxWin,Math.round(base.bet*.25*collected*multiple)),multiplier:multiple};if(full)rewardReel={values:[2,3,5],selected:multiple};remaining=0;}
   rounds.push({board:[...board],bet:base.bet,wins:prize?[prize]:[],payout:prize?.amount||0,bronzeFeature:{before,shifted,moves,newCells,remaining,collected,terminal,prize,rewardReel},roundLabel:'수호대 행진 · '+remaining+'회',roamingMoves:moves.map(m=>({...m,symbol:GUARD,before:0,after:0})),heldAtStart:shifted.flatMap((s,i)=>s===GUARD&&!moves.some(m=>m.to===i)?[{cell:i,symbol:GUARD,value:0}]:[]),presentation:this.presentation});
   if(terminal)break;
  }
  return rounds;
 }
 private freeCount(board:string[]){const n=board.filter(s=>s===BRONZE_SCATTER).length;return n>=5?100:n===4?10:n===3?6:0;}
 private sequence(base:BronzeResult,rng:()=>number,includeBase=true):SpinResult{
  const rounds:BronzeResult[]=includeBase?[base,...this.march(base,rng)]:[];const initial=this.freeCount(base.board);let remaining=initial,awarded=initial,played=0;
  while(remaining>0){remaining--;played++;const next=this.draw(base.bet,rng,true),extra=Math.min(this.freeCount(next.board),100-awarded);remaining+=extra;awarded+=extra;next.freeSpinsAdded=extra||undefined;next.freeSpinsRemaining=remaining;next.roundLabel='청동 무료 '+played+' · 남은 '+remaining+'회';rounds.push(next,...this.march(next,rng));}
  let budget=base.bet*this.maxWin;for(const r of rounds){for(const w of r.wins){w.amount=Math.min(budget,w.amount);budget-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);}
  if(rounds.length===1)return rounds[0];
  return packRounds(rounds,{featureOnly:!initial,freeSpinsAwarded:initial||undefined,featureName:initial?'청동 무료 행진':'청동 수호대 행진',presentation:this.presentation,bonusEndReason:budget===0?'max-win':'spins-exhausted',...(!includeBase?{bonusTriggerRound:{board:[...base.board],bet:base.bet,wins:[],payout:0}}:{})});
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.sequence(this.draw(bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');for(let i=0;i<200000;i++){const board=this.drawBoard(rng);if(this.freeCount(board))return this.sequence(this.evaluate(board,bet),rng,false);}throw Error('Bronze free trigger unavailable');}
 demoSpin(bet:number){let state=410928;const rng=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(r.rounds?.some(q=>(q as BronzeResult).bronzeFeature))return r;}throw Error('Bronze march fixture unavailable');}
}
