import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {WOLF_LINES} from './WolfRules';
import {drawReelBoard} from './ReelScatter';
export const PARK_ID='night-park-board';
export const PARK_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export const PARK_TILES=['출발','선물','관람차','강화','팝콘','한 바퀴 더','풍선','강화','회전목마','선물','한 바퀴 더','축제 보물'];
export const PARK_START=[2,5.6];
export interface ParkMove {sourceCell:number;die:number;from:number;to:number;path:number[];boostBefore:number;boostAfter:number;added:number;win?:Win;}
export interface ParkPlayback {stage:'welcome'|'spin';character:number;before:number;after:number;boostBefore:number;boostAfter:number;moves:ParkMove[];startAward?:Win;}
/** Theme Park Blast-inspired character/board progression. All numeric rules are local. */
export class NightParkSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;readonly usesLocalPayouts=true;
 readonly bonusCalibrationKey=PARK_ID+':board-v1';readonly bonusChoiceCount=2;
 get bonusSymbol(){return PARK_ID+'-scatter';}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'별 세 개로 야간 개장',triggerText:'놀이공원 개장',bonusInText:'함께 걸을 캐릭터를 선택하세요',hitText:'야간 산책 보상',totalWinText:'공원 총 보상',signature:'별 → 주사위 → 경로 이동 → 도착 보상',uiEffect:'보드 이동',soundCue:'featureLand',anticipationHold:.3,hitHold:.3,outHold:.4};
 readonly config:SlotConfig={id:PARK_ID,title:'밤의 놀이공원 산책',subtitle:'NIGHT PARK',tag:'DICE BOARD',color:'#382b51',accent:'#e3b7e8',description:'5×3 · 25라인 · 왼쪽부터3개 이상\n별3개 이상이면 야간 산책5회\n캐릭터마다 시작 보상과 보드 보상이 다릅니다.\n별마다 주사위를 굴려 이동·강화·추가 산책 보상을 받습니다.\n추가 산책을 포함해 최대8회입니다.',symbols:['관람차','회전목마','롤러코스터','입장권','솜사탕','팝콘','선물','풍선','주사위 WILD','별'].map((name,i)=>({id:PARK_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#e3b7e8',weight:[5,6,7,8,10,12,14,16,3,5][i],payout:i<8?PARK_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult {
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid park spin');
  const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<8;s++){const cells:number[]=[];for(const c of line){if(board[c]!==PARK_ID+'-'+s&&board[c]!==PARK_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*PARK_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:PARK_ID+'-'+s,cells,amount};}if(best)wins.push(best);});
  return {board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private draw(bet:number,rng:()=>number){return this.evaluate(drawReelBoard(5,3,this.config.symbols,this.bonusSymbol,rng),bet);}
 private stars(board:string[]){return board.flatMap((s,i)=>s===this.bonusSymbol?[i]:[]);}
 private settle(rounds:SpinResult[]):SpinResult {let left=rounds[0].bet*this.maxWin;for(const r of rounds){for(const w of r.wins){w.amount=Math.min(left,w.amount);left-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);}return{board:[...rounds[rounds.length-1].board],bet:rounds[0].bet,rounds,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),presentation:this.presentation,freeSpinsAwarded:5,featureName:'야간 산책',bonusEndReason:left?'spins-exhausted':'max-win'};}
 private branch(base:SpinResult,character:number,rng:()=>number){
  const copied={...base,board:[...base.board],wins:base.wins.map(w=>({...w,cells:[...w.cells]}))};
  const startAward:Win={line:-1,symbol:this.bonusSymbol,cells:this.stars(base.board),amount:Math.round(base.bet*PARK_START[character])};
  const rounds:SpinResult[]=[copied,{board:[...base.board],bet:base.bet,wins:[startAward],payout:startAward.amount,parkFeature:{stage:'welcome',character,before:0,after:0,boostBefore:1,boostAfter:1,moves:[],startAward}}];
  let position=0,boost=1,total=5;
  for(let played=0;played<total;played++){
   const r=this.draw(base.bet,rng),before=position,boostBefore=boost,moves:ParkMove[]=[];let added=0;
   for(const sourceCell of this.stars(r.board)){
    const die=1+Math.floor(rng()*6),from=position,path=Array.from({length:die},(_,i)=>(from+i+1)%12),prior=boost;position=path[path.length-1];
    let extra=0,win:Win|undefined;
    if(position===3||position===7)boost=Math.min(4,boost+1);
    else if(position===5||position===10){if(total<8){extra=1;total++;added++;}}
    else{const unit=[.8,.8,1.6,0,.6,0,1,0,1.6,1.2,0,6][position];win={line:-1,symbol:this.bonusSymbol,cells:[sourceCell],amount:Math.round(base.bet*unit*boost*(character===0?1:.5))};r.wins.push(win);}
    moves.push({sourceCell,die,from,to:position,path,boostBefore:prior,boostAfter:boost,added:extra,...(win?{win}:{})});
   }
   r.payout=r.wins.reduce((n,w)=>n+w.amount,0);r.parkFeature={stage:'spin',character,before,after:position,boostBefore,boostAfter:boost,moves};r.roundLabel='산책 '+(played+1);if(added)r.freeSpinsAdded=added;rounds.push(r);
  }
  return this.settle(rounds);
 }
 private bonus(base:SpinResult,rng:()=>number){
  // Both characters replay the same random trajectory; only starting/board awards differ.
  const draws:number[]=[];const first=this.branch(base,0,()=>{const n=rng();draws.push(n);return n;});let i=0;
  const second=this.branch(base,1,()=>draws[i++]);
  return {...first,featureChoices:{title:'함께 걸을 캐릭터',labels:['탐험가 · 시작 '+PARK_START[0]+'배 · 보드100%','안내원 · 시작 '+PARK_START[1]+'배 · 보드50%'],defaultIndex:0,results:[first,second]}};
 }
 spin(bet:number,rng:()=>number=Math.random){const base=this.draw(bet,rng);return this.stars(base.board).length>=3?this.bonus(base,rng):base;}
 prepareBonusPurchase(bet:number,rng:()=>number){const base=this.draw(bet,rng);for(const col of [0,2,4])if(![col,col+5,col+10].some(c=>base.board[c]===this.bonusSymbol))base.board[col+5*Math.floor(rng()*3)]=this.bonusSymbol;
  const natural=this.bonus(this.evaluate(base.board,bet),rng),choice=natural.featureChoices;
  const results=choice.results.map(source=>{const rounds=source.rounds!.slice(1),wins=rounds.flatMap(r=>r.wins);return {...source,rounds,wins,payout:wins.reduce((n,w)=>n+w.amount,0),bonusTriggerRound:{board:[...base.board],bet,wins:[],payout:0}};});
  return {...results[0],featureChoices:{...choice,results}};
 }
 demoSpin(bet:number){return this.findDemo(bet,false);}
 bonusDemoSpin(bet:number){return this.findDemo(bet,true);}
 private findDemo(bet:number,bonus:boolean){let seed=320928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.wins.length===1)return r;}throw Error('Park fixture search failed');}
}
