/** Verified rules for Tome of Secrets. Not connected to the live game yet.
 * GRS1485 + official demo help/paytable, checked 2026-09-21.
 * Symbols: 0..7 regular, 8 book, 9 multiplier wild, 10 mega wild, -1 empty.
 * Demo: two multiplier portraits in one nine-ring cluster paid 20 × 2 = 40,
 * not ×4. Mega occupied a 2 × 2 footprint. Full generator/UI still pending.
 */
export const TOME_PAYS: readonly (readonly number[])[] = [
 [2,4,8,16,32,50,100], [1.5,3,6,12,24,30,60],
 [1,2,4,8,16,20,40], [.7,1.5,3,6,12,15,30],
 [.4,.6,1,2,4,4.5,6], [.3,.5,.8,1.6,3.2,4,5],
 [.2,.4,.6,1.2,2.4,3,4], [.1,.2,.3,.6,1.2,1.5,2],
];
export type TomePortalEffect = 'wilds' | 'abyss' | 'void';
export interface TomeCluster {symbol:number;cells:number[];baseMultiple:number;multiplierCells:number[];multiplier:number;multiple:number;}
function validBoard(board:readonly number[]){
 if(board.length!==25||board.some(v=>!Number.isInteger(v)||v < -1||v>10))throw Error('Tome requires a valid 5 × 5 board');
}
function validCount(count:number){if(!Number.isSafeInteger(count)||count<0)throw Error('Invalid Tome portal charge');}
/** Cluster topology only. Payout multipliers are recorded separately, never
 * applied to every cascade globally. Shared wilds are removed/charged once by
 * the caller's union of winning cells. Wild-only groups have no paytable row. */
const TOME_NEIGHBORS=Array.from({length:25},(_,cell)=>{const row=Math.floor(cell/5),col=cell%5;return[row>0?cell-5:-1,row<4?cell+5:-1,col>0?cell-1:-1,col<4?cell+1:-1].filter(n=>n>=0);});
export function tomeClusters(board:readonly number[]):TomeCluster[]{
 validBoard(board);const result:TomeCluster[]=[];
 for(let symbol=0;symbol<8;symbol++){
  let visited=0;
  for(let start=0;start<25;start++){
   if(visited&(1<<start)||(board[start]!==symbol&&board[start]<8))continue;
   const cells:number[]=[],multiplierCells:number[]=[],pending=[start];let regular=false;visited|=1<<start;
   while(pending.length){
    const cell=pending.pop()!;cells.push(cell);regular ||= board[cell]===symbol;if(board[cell]===9)multiplierCells.push(cell);
    for(const next of TOME_NEIGHBORS[cell])if(!(visited&(1<<next))&&(board[next]===symbol||board[next]>=8)){visited|=1<<next;pending.push(next);}
   }
   if(cells.length>=4&&regular){
    const baseMultiple=TOME_PAYS[symbol][Math.min(10,cells.length)-4],multiplier=multiplierCells.length?2:1;
    result.push({symbol,cells:cells.sort((a,b)=>a-b),baseMultiple,multiplierCells,multiplier,multiple:baseMultiple*multiplier});
   }
  }
 }
 return result;
}
/** When two thresholds are crossed before an effect can play, the demo's
 * detailed help explicitly awards only the latest one, not every skipped tier.
 * Call after ordinary cascades settle; persist returned tier after placement. */
export function tomePendingPortal(charge:number,playedTier:number):{tier:number;effect:TomePortalEffect;wildCount:2}|undefined{
 validCount(charge);
 if(!Number.isInteger(playedTier)||playedTier<0||playedTier>3)throw Error('Invalid Tome portal tier');
 const tier=charge>=27?3:charge>=14?2:charge>=7?1:0;
 if(tier<=playedTier||charge>=42)return undefined;
 return{tier,effect:(['wilds','abyss','void'] as const)[tier-1],wildCount:2};
}
/** The bonus is ONE round with a finite effect queue, not 10/15 free spins. */
export function tomeOtherWorldEffects(charge:number):number{
 validCount(charge);return charge<42?0:Math.min(7,3+Math.floor((charge-42)/3));
}
export interface TomeSweep {source:number;axis:'row'|'column';cells:number[];}
/** Follow every book touched by an Abyss sweep. A book triggers once even if
 * intersecting sweeps hit it again. Empty cells cannot add portal charge. */
export function tomeAbyss(board:readonly number[],sources:readonly number[],axis:(source:number)=>'row'|'column'){
 validBoard(board);const pending=[...sources],used=new Set<number>(),removed=new Set<number>(),sweeps:TomeSweep[]=[];
 for(const cell of sources)if(!Number.isInteger(cell)||cell<0||cell>=25||board[cell]!==8)throw Error('Abyss source must be a book wild');
 while(pending.length){
  const source=pending.shift()!;if(used.has(source))continue;used.add(source);
  const direction=axis(source);if(direction!=='row'&&direction!=='column')throw Error('Invalid Abyss direction');
  const cells=Array.from({length:5},(_,i)=>direction==='row'?Math.floor(source/5)*5+i:i*5+source%5).filter(i=>board[i]>=0);
  sweeps.push({source,axis:direction,cells});
  for(const cell of cells){removed.add(cell);if(board[cell]===8&&!used.has(cell))pending.push(cell);}
 }
 return{sweeps,removed:[...Array.from(removed)].sort((a,b)=>a-b)};
}
/** Void removes one regular type; special symbols are never selected. */
export function tomeVoid(board:readonly number[],symbol:number):number[]{
 validBoard(board);if(!Number.isInteger(symbol)||symbol<0||symbol>7)throw Error('Void requires a regular symbol');
 return board.flatMap((value,cell)=>value===symbol?[cell]:[]);
}

export interface TomeFall {from:number;to:number;symbol:number;}
export interface TomeRefill {to:number;symbol:number;}
/** The marks belong to board coordinates, not moving symbols. Keeping them
 * outside the collapse output prevents the Sugar Rush-style position mixup. */
export function tomeOpenEyes(marked:readonly number[],opened:readonly number[],winningCells:readonly number[]){
 for(const cell of [...marked,...opened,...winningCells])if(!Number.isInteger(cell)||cell<0||cell>=25)throw Error('Invalid Tome eye position');
 const marks=new Set(marked),old=new Set(opened);
 if([...Array.from(old)].some(cell=>!marks.has(cell)))throw Error('Opened Tome eye has no mark');
 const newlyOpened=[...Array.from(new Set(winningCells))].filter(cell=>marks.has(cell)&&!old.has(cell));
 const after=[...Array.from(new Set([...opened,...newlyOpened]))].sort((a,b)=>a-b);
 return{newlyOpened,opened:after,complete:marks.size>0&&after.length===marks.size};
}
/** Every paid/effect removal occurs before the refill. A survivor keeps its
 * column/order; only newly created symbols call pick, exactly once per gap.
 * The UI replays drops/refills and never invents a replacement board. */
export function tomeCollapse(board:readonly number[],removed:readonly number[],pick:(cell:number)=>number){
 validBoard(board);const erased=new Set(removed);
 for(const cell of erased)if(!Number.isInteger(cell)||cell<0||cell>=25)throw Error('Invalid Tome removal position');
 const after=Array<number>(25).fill(-1),drops:TomeFall[]=[],refills:TomeRefill[]=[];
 for(let col=0;col<5;col++){
  const kept=Array.from({length:5},(_,row)=>row*5+col).filter(cell=>board[cell]>=0&&!erased.has(cell));
  kept.forEach((from,i)=>{const to=(5-kept.length+i)*5+col;after[to]=board[from];drops.push({from,to,symbol:board[from]});});
  for(let row=0;row<5-kept.length;row++){
   const to=row*5+col,symbol=pick(to);
   if(!Number.isInteger(symbol)||symbol<0||symbol>9)throw Error('Tome refill requires a regular or normal wild symbol');
   after[to]=symbol;refills.push({to,symbol});
  }
 }
 return{board:after,drops,refills};
}
