import {SpinResult} from './SlotMain';
import {RhinoBoard} from './RhinoRules';
import {rhinoBeginSpin,rhinoFinishSpin,rhinoStartBonus} from './RhinoBonus';
import {RHINO_MAX_WIN} from './RhinoResult';

/** Count actual scatter tokens, including the independent top strip. Top-strip
 * compaction can move a surviving token above a reel holding another token. */
export function rhinoScatterCount(board:RhinoBoard){
 return [...board.columns.flat(),...board.top].filter(symbol=>symbol===11).length;
}
export function rhinoSequence(base:SpinResult,choice:number,next:(multiplier:number,budget:number,played:number)=>SpinResult):SpinResult{
 if(!base.rhinoFeature)throw Error('Missing Rhino trigger stages');
 const last=base.rhinoFeature.stages[base.rhinoFeature.stages.length-1];
 const scatters=rhinoScatterCount(last.board),cap=base.bet*RHINO_MAX_WIN;
 if(scatters<4||base.payout>=cap)return base;
 let state=rhinoStartBonus(scatters,choice),paid=base.payout;
 const initial=state.remaining,rounds=[base];
 while(state.phase!=='complete'&&paid<cap){
  if(rounds.length>10000)throw Error('Rhino free spins did not converge');
  const running=rhinoBeginSpin(state),round=next(state.multiplier,cap-paid,rounds.length);
  if(!round.rhinoFeature||round.bet!==base.bet||round.payout>cap-paid)throw Error('Invalid Rhino free round');
  const stages=round.rhinoFeature.stages,final=stages[stages.length-1];
  const winningTumbles=stages.filter(stage=>stage.wins.length>0).length;
  const transition=rhinoFinishSpin(running,winningTumbles,rhinoScatterCount(final.board));
  state=transition.after;paid+=round.payout;
  round.freeSpinsAdded=transition.addedSpins||undefined;
  round.freeSpinsRemaining=state.remaining;
  round.roundLabel=`FREE SPINS · ${rounds.length}회 · 남은 ${state.remaining}회`;
  rounds.push(round);
 }
 return{bet:base.bet,board:[...rounds[rounds.length-1].board],wins:rounds.flatMap(round=>round.wins),payout:paid,rounds,
  freeSpinsAwarded:initial,featureName:'라이노 · 누적 배수',bonusEndReason:paid>=cap?'max-win':'spins-exhausted'};
}
