import type {QuestEvidence} from './QuestPolicy';
import {networkWait} from './NetworkWait';
import {getApps,getAuth,getFirestore,doc,collection,runTransaction,serverTimestamp,getDoc,getDocs,query,orderBy,limit,where,getCountFromServer} from '../vendor/firebase-sdk.js';
import {rankingWeek,WEEK_MS,MIN_RANK_SPINS,WeeklyStats,addRankRounds,rankRows} from './RankingPolicy';
export interface RankingRound {quest?:QuestEvidence;id:string;slot:string;bet:number;payout:number;completedAt:number;name:string;}
export interface RankRow {rank:number;name:string;value:number;spins:number;isMe:boolean;}
export type RankMetric='winRate'|'bigWin'|'moneyOut';
export interface RankingSnapshot {weekStart:number;weekEnd:number;minSpins:number;mySpins:number;winRate:RankRow[];bigWin:RankRow[];moneyOut:RankRow[];winRateMe:RankRow|null;bigWinMe:RankRow|null;moneyOutMe:RankRow|null;previousWinners:Record<RankMetric,RankRow[]>;}
export async function rankingRequest(path:string,_token:string,rounds?:RankingRound[]){
 return networkWait.track(()=>sendRankingRequest(path,_token,rounds));
}
async function sendRankingRequest(path:string,_token:string,rounds?:RankingRound[]){
 const app=getApps().find(a=>a.name==='in-my-pocket');if(!app)throw Error('Not signed in');const user=getAuth(app).currentUser;if(!user)throw Error('Not signed in');const db=getFirestore(app),week=rankingWeek(Date.now()),uid=user.uid;
 if(rounds){const accepted:string[]=[],discarded=rounds.filter(r=>rankingWeek(r.completedAt)!==week).map(r=>r.id),current=rounds.filter(r=>rankingWeek(r.completedAt)===week);
  for(let i=0;i<current.length;i+=10){const batch=current.slice(i,i+10),statsRef=doc(db,'weeklyRankings',String(week),'players',uid);await runTransaction(db,async tx=>{const stats=await tx.get(statsRef),refs=batch.map(r=>doc(statsRef,'rounds',r.id)),receipts=await Promise.all(refs.map(ref=>tx.get(ref))),fresh=batch.filter((_,j)=>!receipts[j].exists());if(!fresh.length)return;
   tx.set(statsRef,{...addRankRounds(stats.exists()?stats.data() as WeeklyStats:undefined,fresh,week),updatedAt:serverTimestamp()});batch.forEach((r,j)=>{if(!receipts[j].exists())tx.set(refs[j],{bet:r.bet,payout:r.payout,slot:r.slot,...(Number.isSafeInteger(r.completedAt)&&r.completedAt>0&&r.completedAt<=Date.now()?{completedAt:r.completedAt}:{}),...(r.quest?{quest:r.quest}:{}),recordedAt:serverTimestamp()});});});accepted.push(...batch.map(r=>r.id));}
  return{accepted,discarded};
 }
 const metrics:RankMetric[]=['winRate','bigWin','moneyOut'];const read=async(start:number)=>{const ref=collection(db,'weeklyRankings',String(start),'players'),result:any={};await Promise.all(metrics.map(async metric=>{const snapshot=await getDocs(query(ref,orderBy(metric,'desc'),limit(50)));result[metric]=rankRows(snapshot.docs.map(d=>({id:d.id,stats:d.data() as WeeklyStats})),metric,uid);}));return result;};
 const [current,previous,mine]=await Promise.all([read(week),read(week-WEEK_MS),getDoc(doc(db,'weeklyRankings',String(week),'players',uid))]);
 const mineStats=mine.exists()?mine.data() as WeeklyStats:null;await Promise.all(metrics.map(async metric=>{current[metric+'Me']=current[metric].find((r:RankRow)=>r.isMe)||null;if(mineStats&&mineStats[metric]>=0&&!current[metric+'Me']){const count=await getCountFromServer(query(collection(db,'weeklyRankings',String(week),'players'),where(metric,'>',mineStats[metric])));current[metric+'Me']={rank:count.data().count+1,name:mineStats.name,value:mineStats[metric],spins:mineStats.spins,isMe:true};}}));
 return{weekStart:week,weekEnd:week+WEEK_MS,minSpins:MIN_RANK_SPINS,...current,mySpins:mineStats?.spins||0,previousWinners:Object.fromEntries(metrics.map(metric=>[metric,previous[metric].filter((r:RankRow)=>r.rank===1)]))};
}
