/** Animate the complete hit together, then remove it before any refill starts.
 * Animation completion (including fast-forward) never owns payout or refill. */
export async function removeRhinoSymbols<T extends {destroy():unknown}>(
 symbols:Map<number,T>,cells:readonly number[],animate:(symbol:T)=>Promise<void>
):Promise<void>{
 const removed=[...Array.from(new Set(cells))].map(cell=>({cell,symbol:symbols.get(cell)}));
 if(removed.some(entry=>!entry.symbol))throw Error('Rhino removal is missing a displayed symbol');
 await Promise.all(removed.map(entry=>animate(entry.symbol!)));
 for(const {cell,symbol} of removed){symbol!.destroy();symbols.delete(cell);}
}
